class ContestApp {
  constructor() {
    this.currentView = 'home';
    this.currentUser = null;
    this.allQuestions = [...DEFAULT_QUESTIONS];
    this.examQuestions = [];
    this.currentQIndex = 0;
    this.userAnswers = [];
    this.flaggedQuestions = [];
    
    // Exam timer & anti-cheat
    this.timerSeconds = 15 * 60; // 15 mins (900s)
    this.timerInterval = null;
    this.startTime = null;
    this.elapsedSeconds = 0;
    this.warningCount = 0;
    this.examActive = false;
    this.lastBlurTime = 0;

    // Results & Admin data
    this.currentResult = null;
    this.submissions = [...DEFAULT_SUBMISSIONS];
    this.schools = [
      "THPT Mường Lầm",
      "THPT Sông Mã",
      "THPT Số 1 Sông Mã",
      "THPT Số 2 Sông Mã",
      "THPT Chuyên Sơn La"
    ];

    this.reviewFilter = 'all';
    this.adminQFilter = 'all';

    // Preload official Youth Union Logo
    this.doanLogoImg = new Image();
    this.doanLogoImg.src = LOGO_DOAN_BASE64;

    this.init();
  }

  async init() {
    this.setupAntiCheatListeners();
    await this.loadQuestions();
    await this.loadSubmissions();

    // Ensure we always have the 56 students of THPT Mường Lầm
    if (!this.submissions || this.submissions.length === 0) {
      this.submissions = [...DEFAULT_SUBMISSIONS];
    }

    // Default currentResult to top student Lò Anh Minh (100đ, 11A1, THPT Mường Lầm)
    if (!this.currentResult && this.submissions.length > 0) {
      const top = this.submissions[0];
      this.currentResult = {
        ...top,
        titleWithEmoji: `${top.title} 🏆`,
        questions: this.allQuestions.slice(0, 20),
        userAnswers: this.allQuestions.slice(0, 20).map(q => q.correct)
      };
      this.currentUser = {
        fullName: top.fullName,
        school: top.school,
        grade: top.grade,
        className: top.className
      };
    }

    this.applyLogoBase64();
    this.loadLeaderboard();
    this.populateSchoolFilters();
    this.populateQuickStudentList();
    this.populateCertificateStudentSwitcher();
    this.renderResultPage();

    // Check URL route or hash
    const path = window.location.pathname;
    const hash = window.location.hash;
    if (path === '/admin' || hash === '#admin') {
      this.navigate('admin');
    } else if (path === '/result' || hash === '#result') {
      this.navigate('result');
    } else {
      this.navigate('home');
    }
  }

  applyLogoBase64() {
    document.querySelectorAll('.logo-doan-img').forEach(img => {
      img.src = LOGO_DOAN_BASE64;
    });
  }

  viewStudentCertificate(subId) {
    this.switchCertificateStudent(subId);
    this.navigate('result');
    window.scrollTo({ top: 300, behavior: 'smooth' });
  }

  // ==================== ROUTING & NAVIGATION ====================
  navigate(viewName) {
    if (this.examActive && viewName !== 'exam') {
      const confirmLeave = confirm("Bài thi đang diễn ra! Nếu rời khỏi phòng thi, kết quả hiện tại sẽ không được lưu. Bạn có chắc chắn muốn rời?");
      if (!confirmLeave) return;
      this.cleanupExamState();
    }

    this.currentView = viewName;
    ['home', 'exam', 'result', 'admin'].forEach(v => {
      const el = document.getElementById(`view-${v}`);
      if (el) {
        if (v === viewName) {
          el.classList.remove('hidden');
        } else {
          el.classList.add('hidden');
        }
      }
    });

    // Update nav active states
    document.querySelectorAll('.nav-tab-btn').forEach(btn => {
      btn.classList.remove('bg-white/20', 'font-bold');
    });
    const activeNavBtn = document.getElementById(`nav-btn-${viewName}`);
    if (activeNavBtn && viewName !== 'exam') {
      activeNavBtn.classList.add('bg-white/20', 'font-bold');
    }

    if (viewName === 'admin') {
      this.renderAdminView();
    } else if (viewName === 'home') {
      this.loadLeaderboard();
    }

    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  // ==================== DATA LOADING ====================
  async loadQuestions() {
    const isStaticHost = window.location.protocol === 'file:' || 
                         window.location.hostname.includes('github.io') ||
                         window.location.hostname.includes('github.com') ||
                         (window.location.port !== '3000' && window.location.port !== '8080');
    if (isStaticHost) {
      this.allQuestions = [...DEFAULT_QUESTIONS];
      return;
    }
    try {
      const res = await fetch('/api/questions');
      if (res.ok) {
        const json = await res.json();
        if (json.data && json.data.length > 0) {
          this.allQuestions = json.data;
          return;
        }
      }
    } catch (err) {}
    this.allQuestions = [...DEFAULT_QUESTIONS];
  }

  async loadSubmissions() {
    const isStaticHost = window.location.protocol === 'file:' || 
                         window.location.hostname.includes('github.io') ||
                         window.location.hostname.includes('github.com') ||
                         (window.location.port !== '3000' && window.location.port !== '8080');
    if (isStaticHost) {
      this.submissions = [...DEFAULT_SUBMISSIONS];
      return;
    }
    try {
      const res = await fetch('/api/submissions');
      if (res.ok) {
        const json = await res.json();
        if (json.data && json.data.length > 0) {
          this.submissions = json.data;
          return;
        }
      }
    } catch (err) {}
    this.submissions = [...DEFAULT_SUBMISSIONS];
  }

  // ==================== HOME & REGISTRATION ====================
  populateQuickStudentList() {
    const sel = document.getElementById('reg-quick-select');
    if (!sel) return;
    sel.innerHTML = '<option value="">-- Bấm vào đây để chọn nhanh học sinh THPT Mường Lầm --</option>';
    this.submissions.forEach((sub, idx) => {
      const opt = document.createElement('option');
      opt.value = sub.id;
      opt.textContent = `${idx + 1}. ${sub.fullName} - Chi đoàn ${sub.className} (Khối ${sub.grade})`;
      sel.appendChild(opt);
    });
  }

  handleQuickStudentSelect(select) {
    const subId = select.value;
    if (!subId) return;
    const sub = this.submissions.find(s => s.id === subId);
    if (!sub) return;

    document.getElementById('reg-fullname').value = sub.fullName;
    document.getElementById('reg-school-select').value = 'THPT Mường Lầm';
    document.getElementById('reg-grade').value = sub.grade || '11';
    document.getElementById('reg-class').value = sub.className;
    
    // Hide custom school input if open
    const customInput = document.getElementById('reg-school-custom');
    if (customInput) {
      customInput.classList.add('hidden');
      customInput.required = false;
    }
  }

  populateCertificateStudentSwitcher() {
    const sel = document.getElementById('cert-student-select');
    if (!sel) return;
    sel.innerHTML = '<option value="">-- Đổi sang chứng nhận của thí sinh khác --</option>';
    this.submissions.forEach((sub, idx) => {
      const opt = document.createElement('option');
      opt.value = sub.id;
      opt.textContent = `${idx + 1}. ${sub.fullName} - ${sub.className} (${sub.score}đ - ${sub.title})`;
      sel.appendChild(opt);
    });
  }

  switchCertificateStudent(subId) {
    if (!subId) return;
    const sub = this.submissions.find(s => s.id === subId);
    if (!sub) return;

    this.currentUser = {
      fullName: sub.fullName,
      school: sub.school || 'THPT Mường Lầm',
      grade: sub.grade,
      className: sub.className
    };

    let emoji = '🌟';
    if (sub.score >= 90) emoji = '🏆';
    else if (sub.score >= 50) emoji = '🎯';
    else emoji = '🤝';

    this.currentResult = {
      ...sub,
      titleWithEmoji: `${sub.title} ${emoji}`,
      questions: this.examQuestions && this.examQuestions.length > 0 ? this.examQuestions : this.allQuestions.slice(0, 20),
      userAnswers: this.userAnswers && this.userAnswers.length > 0 ? this.userAnswers : new Array(20).fill(0)
    };

    this.renderResultPage();
    window.scrollTo({ top: 300, behavior: 'smooth' });
  }

  handleSchoolSelectChange(select) {
    const customInput = document.getElementById('reg-school-custom');
    if (select.value === 'other') {
      customInput.classList.remove('hidden');
      customInput.required = true;
      customInput.focus();
    } else {
      customInput.classList.add('hidden');
      customInput.required = false;
      customInput.value = '';
    }
  }

  startExamFlow() {
    this.navigate('home');
    const form = document.getElementById('form-register');
    if (form) {
      form.scrollIntoView({ behavior: 'smooth' });
      document.getElementById('reg-fullname').focus();
    }
  }

  handleRegisterSubmit(event) {
    event.preventDefault();
    const fullName = document.getElementById('reg-fullname').value.trim();
    const schoolSelect = document.getElementById('reg-school-select').value;
    const schoolCustom = document.getElementById('reg-school-custom').value.trim();
    const school = schoolSelect === 'other' ? schoolCustom : schoolSelect;
    const grade = document.getElementById('reg-grade').value;
    const className = document.getElementById('reg-class').value.trim();

    if (!fullName || !school || !className) {
      alert("Vui lòng nhập đầy đủ thông tin trước khi vào phòng thi!");
      return;
    }

    this.currentUser = {
      fullName,
      school,
      grade,
      className,
      regTime: new Date()
    };

    localStorage.setItem('gyc_user', JSON.stringify(this.currentUser));
    this.startExam();
  }

  loadLeaderboard() {
    const container = document.getElementById('home-leaderboard-list');
    if (!container) return;

    if (!this.submissions || this.submissions.length === 0) {
      container.innerHTML = `
        <div class="text-center py-8 text-slate-400 text-xs">
          Chưa có thí sinh dự thi. Hãy là người đầu tiên!
        </div>
      `;
      return;
    }

    const topSubmissions = [...this.submissions]
      .sort((a, b) => b.score - a.score || (a.durationSeconds || 0) - (b.durationSeconds || 0))
      .slice(0, 10);

    let html = '';
    topSubmissions.forEach((sub, idx) => {
      let rankBadge = `<span class="w-6 h-6 rounded-full bg-slate-100 text-slate-600 font-bold text-xs flex items-center justify-center">${idx + 1}</span>`;
      let rankCardStyle = 'bg-slate-50 border-slate-200/60';

      if (idx === 0) {
        rankBadge = `<span class="w-6 h-6 rounded-full bg-amber-400 text-slate-950 font-black text-xs flex items-center justify-center shadow">🥇</span>`;
        rankCardStyle = 'bg-amber-50/70 border-amber-200/80';
      } else if (idx === 1) {
        rankBadge = `<span class="w-6 h-6 rounded-full bg-slate-300 text-slate-900 font-black text-xs flex items-center justify-center shadow">🥈</span>`;
        rankCardStyle = 'bg-slate-100/70 border-slate-300/80';
      } else if (idx === 2) {
        rankBadge = `<span class="w-6 h-6 rounded-full bg-amber-700 text-white font-black text-xs flex items-center justify-center shadow">🥉</span>`;
        rankCardStyle = 'bg-orange-50/70 border-orange-200/80';
      }

      html += `
        <div onclick="app.viewStudentCertificate('${sub.id}')" class="flex items-center justify-between p-3 rounded-xl border ${rankCardStyle} transition-all hover:scale-[1.01] cursor-pointer hover:shadow-md">
          <div class="flex items-center gap-3">
            ${rankBadge}
            <div>
              <div class="font-bold text-slate-800 text-xs sm:text-sm flex items-center gap-1.5">
                <span>${this.escapeHtml(sub.fullName)}</span>
                <span class="text-[10px] bg-blue-100 text-blue-700 font-semibold px-1.5 py-0.2 rounded">${this.escapeHtml(sub.className || '')}</span>
              </div>
              <div class="text-[11px] text-slate-500 truncate max-w-[180px] sm:max-w-xs">${this.escapeHtml(sub.school)}</div>
            </div>
          </div>
          <div class="flex items-center gap-2">
            <div class="text-right">
              <div class="font-extrabold text-blue-700 text-sm sm:text-base">${sub.score} <span class="text-[10px] text-slate-400 font-normal">đ</span></div>
              <div class="text-[10px] font-mono text-slate-400">${sub.durationFormatted || '15:00'}</div>
            </div>
            <button onclick="event.stopPropagation(); app.viewStudentCertificate('${sub.id}')" class="px-2.5 py-1 rounded-lg bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-[10px] shadow-sm flex items-center gap-0.5" title="Xem & Tải Giấy Chứng Nhận">
              <span>Xem Bằng</span>
            </button>
          </div>
        </div>
      `;
    });

    container.innerHTML = html;
  }

  // ==================== EXAM ENGINE ====================
  startExam() {
    if (!this.currentUser) {
      this.navigate('home');
      return;
    }

    // Pick 20 questions: exactly 12 from Part 1, 8 from Part 2
    const part1Questions = this.allQuestions.filter(q => Number(q.part) === 1);
    const part2Questions = this.allQuestions.filter(q => Number(q.part) === 2);

    const shuffle = arr => [...arr].sort(() => 0.5 - Math.random());

    const selectedP1 = shuffle(part1Questions).slice(0, 12);
    const selectedP2 = shuffle(part2Questions).slice(0, 8);

    this.examQuestions = [...selectedP1, ...selectedP2];
    
    // In case of fallback
    if (this.examQuestions.length < 20) {
      this.examQuestions = shuffle(this.allQuestions).slice(0, 20);
    }

    this.currentQIndex = 0;
    this.userAnswers = new Array(this.examQuestions.length).fill(null);
    this.flaggedQuestions = new Array(this.examQuestions.length).fill(false);
    this.timerSeconds = 15 * 60; // 15 mins
    this.warningCount = 0;
    this.examActive = true;
    this.startTime = Date.now();

    // Update Header Student Info
    document.getElementById('exam-student-name').textContent = this.currentUser.fullName;
    document.getElementById('exam-student-class').textContent = this.currentUser.className;
    document.getElementById('exam-student-school').textContent = this.currentUser.school;
    
    // Avatar initials
    const nameParts = this.currentUser.fullName.split(' ');
    const initials = nameParts.length > 1 
      ? (nameParts[nameParts.length - 2][0] + nameParts[nameParts.length - 1][0]).toUpperCase()
      : this.currentUser.fullName.substring(0, 2).toUpperCase();
    document.getElementById('exam-avatar-initials').textContent = initials;

    this.updateViolationBadge();
    this.startTimer();
    this.renderPalette();
    this.renderCurrentQuestion();
    this.updateProgress();

    this.navigate('exam');
  }

  startTimer() {
    if (this.timerInterval) clearInterval(this.timerInterval);

    const timerEl = document.getElementById('exam-timer');
    const updateDisplay = () => {
      const minutes = Math.floor(this.timerSeconds / 60);
      const seconds = this.timerSeconds % 60;
      const str = `${minutes < 10 ? '0' : ''}${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
      if (timerEl) {
        timerEl.textContent = str;
        if (this.timerSeconds <= 120) {
          timerEl.classList.add('timer-danger');
        } else {
          timerEl.classList.remove('timer-danger');
        }
      }
    };

    updateDisplay();

    this.timerInterval = setInterval(() => {
      if (!this.examActive) return;
      this.timerSeconds--;
      this.elapsedSeconds++;
      updateDisplay();

      if (this.timerSeconds <= 0) {
        clearInterval(this.timerInterval);
        alert("Hết giờ làm bài thi (15 phút)! Hệ thống sẽ tự động nộp bài.");
        this.executeSubmitExam(false);
      }
    }, 1000);
  }

  renderPalette() {
    const grid = document.getElementById('exam-palette-grid');
    if (!grid) return;

    let html = '';
    for (let i = 0; i < this.examQuestions.length; i++) {
      let stateClass = 'bg-slate-100 text-slate-700 border-slate-200 hover:bg-slate-200';
      if (this.userAnswers[i] !== null) {
        stateClass = 'pal-btn-answered';
      }
      if (this.flaggedQuestions[i]) {
        stateClass += ' pal-btn-flagged';
      }
      if (i === this.currentQIndex) {
        stateClass += ' pal-btn-current';
      }

      html += `
        <button onclick="app.jumpToQuestion(${i})" class="h-9 rounded-xl font-bold text-xs border transition-all flex items-center justify-center ${stateClass}">
          ${i + 1}
        </button>
      `;
    }
    grid.innerHTML = html;
  }

  renderCurrentQuestion() {
    if (!this.examQuestions || this.examQuestions.length === 0) return;
    const q = this.examQuestions[this.currentQIndex];

    document.getElementById('q-current-index').textContent = this.currentQIndex + 1;
    document.getElementById('q-part-badge').textContent = q.part === 2 
      ? 'Phần 2: Kiến thức Hội nhập quốc tế & ASEAN' 
      : 'Phần 1: Tiếng Anh giao tiếp A1–A2';
    document.getElementById('q-part-badge').className = q.part === 2 
      ? 'px-3 py-1 rounded-full text-xs font-bold bg-amber-100 text-amber-800'
      : 'px-3 py-1 rounded-full text-xs font-bold bg-blue-100 text-blue-700';

    document.getElementById('q-category-badge').textContent = q.category || (q.part === 2 ? 'ASEAN' : 'Giao tiếp');
    document.getElementById('q-content-text').textContent = q.question;

    const flagBtn = document.getElementById('btn-flag-review');
    const flagText = document.getElementById('flag-btn-text');
    if (this.flaggedQuestions[this.currentQIndex]) {
      flagBtn.classList.add('bg-amber-100', 'border-amber-400', 'text-amber-800');
      flagText.textContent = 'Đã đánh dấu xem lại';
    } else {
      flagBtn.classList.remove('bg-amber-100', 'border-amber-400', 'text-amber-800');
      flagText.textContent = 'Đánh dấu xem lại';
    }

    const optContainer = document.getElementById('q-options-container');
    const letters = ['A', 'B', 'C', 'D'];
    let optHtml = '';

    q.options.forEach((opt, idx) => {
      const isSelected = this.userAnswers[this.currentQIndex] === idx;
      const borderClass = isSelected 
        ? 'border-blue-600 bg-blue-50/80 shadow-md ring-1 ring-blue-500' 
        : 'border-slate-200 hover:border-blue-300 hover:bg-slate-50/60 bg-white';
      const badgeClass = isSelected 
        ? 'bg-blue-600 text-white font-bold' 
        : 'bg-slate-100 text-slate-700 font-bold';

      optHtml += `
        <button type="button" onclick="app.selectOption(${idx})" class="w-full text-left p-3.5 sm:p-4 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-3.5 ${borderClass}">
          <span class="w-7 h-7 rounded-lg flex-shrink-0 flex items-center justify-center text-xs transition-colors ${badgeClass}">
            ${letters[idx]}
          </span>
          <span class="text-xs sm:text-sm font-medium text-slate-800 pt-0.5 leading-relaxed">
            ${this.escapeHtml(opt)}
          </span>
        </button>
      `;
    });
    optContainer.innerHTML = optHtml;

    const btnPrev = document.getElementById('btn-prev-q');
    const btnNext = document.getElementById('btn-next-q');
    btnPrev.disabled = this.currentQIndex === 0;
    btnPrev.classList.toggle('opacity-50', this.currentQIndex === 0);
    btnPrev.classList.toggle('cursor-not-allowed', this.currentQIndex === 0);

    if (this.currentQIndex === this.examQuestions.length - 1) {
      btnNext.innerHTML = `<span>Kiểm Tra & Nộp Bài</span><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>`;
      btnNext.className = "px-5 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs sm:text-sm shadow transition-all flex items-center gap-1.5";
    } else {
      btnNext.innerHTML = `<span>Câu Tiếp Theo</span><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>`;
      btnNext.className = "px-5 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-semibold text-xs sm:text-sm shadow transition-all flex items-center gap-1.5";
    }

    this.renderPalette();
  }

  selectOption(idx) {
    if (!this.examActive) return;
    this.userAnswers[this.currentQIndex] = idx;
    this.renderCurrentQuestion();
    this.updateProgress();
  }

  toggleFlagCurrentQuestion() {
    this.flaggedQuestions[this.currentQIndex] = !this.flaggedQuestions[this.currentQIndex];
    this.renderCurrentQuestion();
  }

  jumpToQuestion(idx) {
    if (idx >= 0 && idx < this.examQuestions.length) {
      this.currentQIndex = idx;
      this.renderCurrentQuestion();
    }
  }

  nextQuestion() {
    if (this.currentQIndex < this.examQuestions.length - 1) {
      this.currentQIndex++;
      this.renderCurrentQuestion();
    } else {
      this.promptSubmitExam();
    }
  }

  prevQuestion() {
    if (this.currentQIndex > 0) {
      this.currentQIndex--;
      this.renderCurrentQuestion();
    }
  }

  updateProgress() {
    const answeredCount = this.userAnswers.filter(a => a !== null).length;
    const total = this.examQuestions.length;
    const percent = Math.round((answeredCount / total) * 100);

    const pBar = document.getElementById('exam-progress-bar');
    const pPercent = document.getElementById('exam-progress-percent');
    const pAnswered = document.getElementById('exam-answered-count');
    const pRemain = document.getElementById('exam-remaining-count');

    if (pBar) pBar.style.width = `${percent}%`;
    if (pPercent) pPercent.textContent = `${percent}%`;
    if (pAnswered) pAnswered.textContent = answeredCount;
    if (pRemain) pRemain.textContent = total - answeredCount;
  }

  promptSubmitExam() {
    const answeredCount = this.userAnswers.filter(a => a !== null).length;
    const total = this.examQuestions.length;
    const unAnswered = total - answeredCount;

    document.getElementById('confirm-answered-count').textContent = `${answeredCount} câu`;
    document.getElementById('confirm-unanswered-count').textContent = `${unAnswered} câu`;

    document.getElementById('modal-confirm-submit').classList.remove('hidden');
  }

  closeSubmitModal() {
    document.getElementById('modal-confirm-submit').classList.add('hidden');
  }

  // ==================== ANTI-CHEAT SYSTEM ====================
  setupAntiCheatListeners() {
    const handleViolation = (reason) => {
      if (!this.examActive) return;

      const now = Date.now();
      if (now - this.lastBlurTime < 2500) return;
      this.lastBlurTime = now;

      this.warningCount++;
      this.updateViolationBadge();
      this.playWarningBeep();

      if (this.warningCount > 2) {
        this.dismissAntiCheatModal();
        alert("VI PHẠM QUY CHẾ: Bạn đã rời khỏi màn hình làm bài quá 2 lần! Hệ thống tự động khóa và nộp bài thi ngay lập tức.");
        this.executeSubmitExam(true);
      } else {
        const modal = document.getElementById('modal-anti-cheat');
        const countEl = document.getElementById('ac-violation-count');
        const subtextEl = document.getElementById('ac-warning-subtext');
        
        countEl.textContent = `${this.warningCount} / 2`;
        if (this.warningCount === 2) {
          subtextEl.innerHTML = `<span class="font-bold underline">CẢNH BÁO CUỐI CÙNG:</span> Nếu rời khỏi màn hình 1 lần nữa, bài thi sẽ bị TỰ ĐỘNG NỘP NGAY LẬP TỨC!`;
        } else {
          subtextEl.textContent = `Lưu ý: Nếu vi phạm lần thứ 3, hệ thống sẽ TỰ ĐỘNG NỘP BÀI ngay lập tức!`;
        }

        modal.classList.remove('hidden');
      }
    };

    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') {
        handleViolation('Tab switched');
      }
    });

    window.addEventListener('blur', () => {
      handleViolation('Window blurred');
    });
  }

  dismissAntiCheatModal() {
    document.getElementById('modal-anti-cheat').classList.add('hidden');
  }

  updateViolationBadge() {
    const badge = document.getElementById('exam-violation-badge');
    if (!badge) return;

    badge.textContent = `${this.warningCount} / 2 lần`;
    if (this.warningCount === 0) {
      badge.className = 'font-bold px-2 py-0.5 rounded bg-emerald-100 text-emerald-700';
    } else if (this.warningCount === 1) {
      badge.className = 'font-bold px-2 py-0.5 rounded bg-amber-100 text-amber-800';
    } else {
      badge.className = 'font-bold px-2 py-0.5 rounded bg-red-100 text-red-700 animate-pulse';
    }
  }

  playWarningBeep() {
    try {
      const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(440, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(880, audioCtx.currentTime + 0.3);
      gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.3);
    } catch(e) {}
  }

  toggleFullScreen() {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(err => {
        console.warn(`Fullscreen: ${err.message}`);
      });
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
      }
    }
  }

  cleanupExamState() {
    this.examActive = false;
    if (this.timerInterval) clearInterval(this.timerInterval);
    this.closeSubmitModal();
    this.dismissAntiCheatModal();
  }

  // ==================== SUBMISSION & RESULT ====================
  async executeSubmitExam(isForced = false) {
    this.cleanupExamState();

    let correctCount = 0;
    let part1Correct = 0;
    let part2Correct = 0;

    this.examQuestions.forEach((q, idx) => {
      const userAns = this.userAnswers[idx];
      if (userAns !== null && userAns === q.correct) {
        correctCount++;
        if (Number(q.part) === 1) part1Correct++;
        else part2Correct++;
      }
    });

    const totalQuestions = this.examQuestions.length;
    const score = Math.round((correctCount / totalQuestions) * 100);

    const durationSec = Math.max(1, (15 * 60) - this.timerSeconds);
    const m = Math.floor(durationSec / 60);
    const s = durationSec % 60;
    const durationFormatted = `${m < 10 ? '0' : ''}${m}:${s < 10 ? '0' : ''}${s}`;

    let title = 'Công dân Toàn cầu Tiềm năng';
    if (score >= 90) {
      title = 'Đại sứ Hội nhập Xuất sắc 🏆';
    } else if (score >= 75) {
      title = 'Công dân Toàn cầu Tiềm năng 🌟';
    } else if (score >= 50) {
      title = 'Thanh niên Hội nhập Tích cực 🎯';
    } else {
      title = 'Chiến sĩ Lan tỏa Văn hóa 🤝';
    }

    const sbdNumber = 1000 + this.submissions.length + 1;
    const submissionData = {
      id: `SUB-${sbdNumber}`,
      fullName: this.currentUser.fullName,
      school: this.currentUser.school,
      grade: this.currentUser.grade,
      className: this.currentUser.className,
      score,
      correctCount,
      totalQuestions,
      part1Correct,
      part2Correct,
      durationSeconds: durationSec,
      durationFormatted,
      title: title.replace(/ [🏆🌟🎯🤝]/g, ''),
      warningsCount: this.warningCount,
      submittedAt: new Date().toISOString().replace('T', ' ').substring(0, 19),
      isForced
    };

    this.currentResult = {
      ...submissionData,
      titleWithEmoji: title,
      questions: this.examQuestions,
      userAnswers: this.userAnswers
    };

    // Save to submissions
    this.submissions.unshift(submissionData);
    localStorage.setItem('gyc_submissions', JSON.stringify(this.submissions));

    // Try posting to API
    try {
      await fetch('/api/submissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(submissionData)
      });
    } catch (err) {}

    this.renderResultPage();
    this.navigate('result');

    if (typeof confetti === 'function') {
      confetti({
        particleCount: 120,
        spread: 80,
        origin: { y: 0.6 }
      });
    }
  }

  renderResultPage() {
    const res = this.currentResult;
    if (!res) return;

    document.getElementById('result-candidate-name').textContent = res.fullName;
    document.getElementById('result-candidate-info').textContent = `Lớp ${res.className} • ${res.school}`;
    document.getElementById('result-score').textContent = res.score;
    document.getElementById('result-duration').textContent = res.durationFormatted;
    document.getElementById('result-title-badge').textContent = res.titleWithEmoji;

    document.getElementById('result-part1-score').textContent = `${res.part1Correct}/12 câu (${res.part1Correct * 5}đ)`;
    document.getElementById('result-part2-score').textContent = `${res.part2Correct}/8 câu (${res.part2Correct * 5}đ)`;
    
    const warnEl = document.getElementById('result-warnings-score');
    if (res.warningsCount === 0) {
      warnEl.textContent = '0 vi phạm (Chuẩn mực)';
      warnEl.className = 'font-bold text-emerald-300 text-sm';
    } else {
      warnEl.textContent = `${res.warningsCount} lần cảnh báo`;
      warnEl.className = 'font-bold text-amber-300 text-sm';
    }

    this.drawCertificateCanvas();
    this.renderDetailedReview();
  }

  // ==================== HIGH RESOLUTION E-CERTIFICATE ====================
  drawCertificateCanvas() {
    const canvas = document.getElementById('cert-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const res = this.currentResult || {
      fullName: 'LÒ ANH MINH',
      school: 'THPT Mường Lầm',
      className: '11A1',
      score: 100,
      title: 'Đại sứ Hội nhập Xuất sắc',
      id: 'ML-1001'
    };

    const width = 2000;
    const height = 1414;
    canvas.width = width;
    canvas.height = height;

    // Background
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, '#ffffff');
    bgGrad.addColorStop(0.5, '#fefdfb');
    bgGrad.addColorStop(1, '#f9f6f0');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Outer Gold Border
    ctx.strokeStyle = '#b4832c';
    ctx.lineWidth = 14;
    ctx.strokeRect(40, 40, width - 80, height - 80);

    // Inner Thin Gold Line
    ctx.strokeStyle = '#e6ca65';
    ctx.lineWidth = 4;
    ctx.strokeRect(55, 55, width - 110, height - 110);

    // Deep Blue Accent Inner Border
    ctx.strokeStyle = '#1e3a8a';
    ctx.lineWidth = 2;
    ctx.strokeRect(65, 65, width - 130, height - 130);

    // Corner Ornaments
    const drawCorner = (cx, cy, angle) => {
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(angle);
      ctx.strokeStyle = '#b4832c';
      ctx.lineWidth = 4;
      
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(80, 0);
      ctx.lineTo(80, 20);
      ctx.lineTo(20, 20);
      ctx.lineTo(20, 80);
      ctx.lineTo(0, 80);
      ctx.closePath();
      ctx.fillStyle = '#fef3c7';
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = '#b4832c';
      ctx.beginPath();
      ctx.arc(35, 35, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    };

    drawCorner(75, 75, 0);
    drawCorner(width - 75, 75, Math.PI / 2);
    drawCorner(width - 75, height - 75, Math.PI);
    drawCorner(75, height - 75, -Math.PI / 2);

    // Header Emblem: Official Ho Chi Minh Communist Youth Union Logo
    ctx.save();
    const logoW = 125;
    const logoH = 140;
    const logoX = (width - logoW) / 2;
    const logoY = 95;

    if (this.doanLogoImg && this.doanLogoImg.complete && this.doanLogoImg.naturalWidth > 0) {
      ctx.drawImage(this.doanLogoImg, logoX, logoY, logoW, logoH);
    } else {
      // Golden circle fallback while loading
      const emblemX = width / 2;
      const emblemY = 165;
      ctx.fillStyle = '#b4832c';
      ctx.beginPath();
      ctx.arc(emblemX, emblemY, 48, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#dc2626';
      ctx.beginPath();
      ctx.arc(emblemX, emblemY, 42, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#fef08a';
      ctx.beginPath();
      for (let i = 0; i < 5; i++) {
        ctx.lineTo(
          emblemX + 24 * Math.cos((18 + i * 72) * Math.PI / 180),
          emblemY - 24 * Math.sin((18 + i * 72) * Math.PI / 180)
        );
        ctx.lineTo(
          emblemX + 10 * Math.cos((54 + i * 72) * Math.PI / 180),
          emblemY - 10 * Math.sin((54 + i * 72) * Math.PI / 180)
        );
      }
      ctx.closePath();
      ctx.fill();

      // Trigger redraw once loaded
      if (this.doanLogoImg) {
        this.doanLogoImg.onload = () => this.drawCertificateCanvas();
      }
    }
    ctx.restore();

    // Organization Header Text
    ctx.textAlign = 'center';
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 26px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('ĐOÀN TNCS HỒ CHÍ MINH XÃ MƯỜNG LẦM - BAN TỔ CHỨC CUỘC THI', width / 2, 260);

    ctx.fillStyle = '#b45309';
    ctx.font = 'bold 22px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('GLOBAL YOUTH CONTEST 2026 • HỘI NHẬP QUỐC TẾ THPT', width / 2, 295);

    // Title Divider
    ctx.strokeStyle = '#d97706';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(width / 2 - 250, 325);
    ctx.lineTo(width / 2 + 250, 325);
    ctx.stroke();

    // Main Heading
    ctx.fillStyle = '#0f172a';
    ctx.font = '900 68px "Playfair Display", Georgia, serif';
    ctx.fillText('GIẤY CHỨNG NHẬN', width / 2, 415);

    ctx.fillStyle = '#b4832c';
    ctx.font = 'italic 700 28px "Playfair Display", Georgia, serif';
    ctx.fillText('CERTIFICATE OF ACHIEVEMENT', width / 2, 460);

    // Presentation text
    ctx.fillStyle = '#475569';
    ctx.font = '500 24px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('Ban Tổ Chức trân trọng công nhận và trao tặng cho:', width / 2, 530);

    // Recipient Name
    ctx.fillStyle = '#1e3a8a';
    ctx.font = '900 56px "Plus Jakarta Sans", sans-serif';
    ctx.fillText((res.fullName || 'HỌC SINH').toUpperCase(), width / 2, 610);

    // Class & School
    ctx.fillStyle = '#334155';
    ctx.font = 'bold 30px "Plus Jakarta Sans", sans-serif';
    ctx.fillText(`Lớp ${res.className || '11A1'} — ${res.school || 'Trường THPT'}`, width / 2, 670);

    // Achievement Description
    ctx.fillStyle = '#475569';
    ctx.font = '400 24px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('Đã hoàn thành xuất sắc Cuộc thi trực tuyến "Tiếng Anh & Hội nhập Quốc tế"', width / 2, 735);
    ctx.fillText('dành cho Đoàn viên, học sinh các trường Trung học Phổ thông năm 2026', width / 2, 775);

    // Result Badge Box
    ctx.save();
    const boxWidth = 900;
    const boxHeight = 130;
    const boxX = (width - boxWidth) / 2;
    const boxY = 825;

    ctx.fillStyle = '#f8fafc';
    ctx.strokeStyle = '#cbd5e1';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.roundRect(boxX, boxY, boxWidth, boxHeight, 20);
    ctx.fill();
    ctx.stroke();

    // Score Column
    ctx.textAlign = 'center';
    ctx.fillStyle = '#64748b';
    ctx.font = 'bold 18px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('KẾT QUẢ ĐẠT ĐƯỢC', boxX + 220, boxY + 45);

    ctx.fillStyle = '#dc2626';
    ctx.font = '900 52px "Plus Jakarta Sans", sans-serif';
    ctx.fillText(`${res.score}`, boxX + 190, boxY + 105);
    ctx.fillStyle = '#94a3b8';
    ctx.font = 'bold 26px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('/100', boxX + 260, boxY + 105);

    // Divider
    ctx.strokeStyle = '#e2e8f0';
    ctx.beginPath();
    ctx.moveTo(boxX + 400, boxY + 20);
    ctx.lineTo(boxX + 400, boxY + 110);
    ctx.stroke();

    // Title Column
    ctx.fillStyle = '#64748b';
    ctx.font = 'bold 18px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('DANH HIỆU VINH DANH', boxX + 650, boxY + 45);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = '800 32px "Plus Jakarta Sans", sans-serif';
    ctx.fillText(res.title || 'Công dân Toàn cầu Tiềm năng', boxX + 650, boxY + 95);
    ctx.restore();

    // Footer - Verification Code & Official Stamp
    const today = new Date();
    const dateStr = `Ngày ${today.getDate()} tháng ${today.getMonth() + 1} năm ${today.getFullYear()}`;
    const certCode = `GYC-2026-${(res.id || 'SUB1000').replace('SUB-', '')}`;

    ctx.textAlign = 'left';
    ctx.fillStyle = '#64748b';
    ctx.font = '18px "Plus Jakarta Sans", sans-serif';
    ctx.fillText(`Mã chứng nhận: ${certCode}`, 160, 1070);
    ctx.fillText(`Xác thực trực tuyến: portal.youthintegration.edu.vn`, 160, 1100);

    // QR Code Frame
    ctx.strokeStyle = '#cbd5e1';
    ctx.lineWidth = 2;
    ctx.strokeRect(160, 1130, 90, 90);
    ctx.fillStyle = '#1e3a8a';
    ctx.fillRect(170, 1140, 20, 20);
    ctx.fillRect(220, 1140, 20, 20);
    ctx.fillRect(170, 1190, 20, 20);
    ctx.fillRect(200, 1170, 15, 15);
    ctx.fillRect(225, 1195, 15, 15);
    ctx.fillStyle = '#94a3b8';
    ctx.font = '11px sans-serif';
    ctx.fillText('Mã QR tra cứu', 160, 1245);

    // Right Footer: Date & Stamp
    ctx.textAlign = 'center';
    ctx.fillStyle = '#475569';
    ctx.font = 'italic 20px "Plus Jakarta Sans", sans-serif';
    ctx.fillText(dateStr, width - 360, 1050);

    ctx.fillStyle = '#1e293b';
    ctx.font = 'bold 22px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('TM. BAN CHẤP HÀNH ĐOÀN XÃ MƯỜNG LẦM', width - 360, 1085);

    // Stamp
    ctx.save();
    const stampX = width - 440;
    const stampY = 1175;

    ctx.strokeStyle = 'rgba(220, 38, 38, 0.85)';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(stampX, stampY, 65, 0, Math.PI * 2);
    ctx.stroke();

    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(stampX, stampY, 57, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = 'rgba(220, 38, 38, 0.85)';
    ctx.font = 'bold 11px sans-serif';
    ctx.fillText('★ ĐOÀN TNCS HỒ CHÍ MINH ★', stampX, stampY - 35);
    ctx.font = 'bold 12px sans-serif';
    ctx.fillText('BCH ĐOÀN', stampX, stampY - 6);
    ctx.fillText('XÃ MƯỜNG LẦM', stampX, stampY + 14);
    ctx.font = '10px sans-serif';
    ctx.fillText('★ BAN TỔ CHỨC CUỘC THI ★', stampX, stampY + 38);
    ctx.restore();

    // Signature flourish
    ctx.save();
    ctx.strokeStyle = '#1e3a8a';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(width - 400, 1170);
    ctx.bezierCurveTo(width - 370, 1140, width - 340, 1200, width - 300, 1160);
    ctx.bezierCurveTo(width - 270, 1130, width - 260, 1210, width - 220, 1175);
    ctx.stroke();
    ctx.restore();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 24px "Plus Jakarta Sans", sans-serif';
    ctx.fillText('ThS. Nguyễn Văn Hoà', width - 360, 1250);
  }

  downloadCertificatePNG() {
    const canvas = document.getElementById('cert-canvas');
    if (!canvas) return;

    const candidateName = (this.currentResult && this.currentResult.fullName) 
      ? this.currentResult.fullName.replace(/\s+/g, '_') 
      : 'Thi_Sinh';

    const link = document.createElement('a');
    link.download = `Giay_Chung_Nhan_Hoi_Nhap_Quoc_Te_${candidateName}.png`;
    link.href = canvas.toDataURL('image/png');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  shareResult() {
    if (!this.currentResult) return;
    const shareText = `Tự hào đạt ${this.currentResult.score}/100 điểm với danh hiệu "${this.currentResult.title}" tại Cuộc thi trực tuyến Tiếng Anh & Hội nhập quốc tế THPT 2026! 🏆🌟`;
    
    if (navigator.clipboard) {
      navigator.clipboard.writeText(shareText + ' ' + window.location.href).then(() => {
        alert("Đã sao chép nội dung chia sẻ vào bộ nhớ tạm! Bạn có thể dán lên Facebook, Zalo để chia sẻ với bạn bè.");
      }).catch(() => {
        alert(shareText);
      });
    } else {
      alert(shareText);
    }
  }

  // ==================== DETAILED REVIEW ====================
  filterReview(type) {
    this.reviewFilter = type;
    document.querySelectorAll('.review-filter-btn').forEach(btn => {
      btn.className = 'review-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 text-slate-600 hover:bg-slate-200';
    });
    const activeBtn = document.getElementById(`rf-${type}`);
    if (activeBtn) {
      activeBtn.className = 'review-filter-btn px-3 py-1.5 rounded-lg text-xs font-bold bg-blue-600 text-white';
    }
    this.renderDetailedReview();
  }

  renderDetailedReview() {
    const container = document.getElementById('review-list-container');
    if (!container || !this.currentResult) return;

    const questions = this.currentResult.questions;
    const userAnswers = this.currentResult.userAnswers;
    const letters = ['A', 'B', 'C', 'D'];

    let html = '';
    let filteredCount = 0;

    questions.forEach((q, idx) => {
      const userAns = userAnswers[idx];
      const isCorrect = userAns === q.correct;

      if (this.reviewFilter === 'wrong' && isCorrect) return;
      if (this.reviewFilter === 'part1' && Number(q.part) !== 1) return;
      if (this.reviewFilter === 'part2' && Number(q.part) !== 2) return;

      filteredCount++;

      const statusBadge = isCorrect
        ? `<span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-emerald-100 text-emerald-700 text-xs font-bold">✓ Làm đúng (+5đ)</span>`
        : `<span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-red-100 text-red-700 text-xs font-bold">✕ Làm sai (0đ)</span>`;

      const partBadge = q.part === 2
        ? `<span class="text-[11px] font-bold text-amber-700 bg-amber-100 px-2 py-0.5 rounded">Phần 2: Hội nhập quốc tế</span>`
        : `<span class="text-[11px] font-bold text-blue-700 bg-blue-100 px-2 py-0.5 rounded">Phần 1: Tiếng Anh A1-A2</span>`;

      html += `
        <div class="rounded-2xl border ${isCorrect ? 'border-slate-200' : 'border-red-200 bg-red-50/20'} p-4 sm:p-5 space-y-3.5 transition-all">
          <div class="flex items-center justify-between flex-wrap gap-2">
            <div class="flex items-center gap-2">
              <span class="w-6 h-6 rounded-lg bg-slate-800 text-white text-xs font-bold flex items-center justify-center">${idx + 1}</span>
              ${partBadge}
              <span class="text-[11px] text-slate-500 font-medium">${q.category || ''}</span>
            </div>
            ${statusBadge}
          </div>

          <div class="text-sm sm:text-base font-semibold text-slate-800">
            ${this.escapeHtml(q.question)}
          </div>

          <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
            ${q.options.map((opt, optIdx) => {
              let optStyle = 'border-slate-200 bg-white text-slate-700';
              let optIcon = '';

              if (optIdx === q.correct) {
                optStyle = 'border-emerald-500 bg-emerald-50 text-emerald-900 font-bold';
                optIcon = ' ✓ Đáp án đúng';
              }
              if (userAns === optIdx && optIdx !== q.correct) {
                optStyle = 'border-red-400 bg-red-50 text-red-900 font-semibold line-through';
                optIcon = ' ✕ Bạn đã chọn';
              } else if (userAns === optIdx && optIdx === q.correct) {
                optIcon = ' ✓ Bạn đã chọn đúng';
              }

              return `
                <div class="p-2.5 rounded-xl border flex items-center justify-between ${optStyle}">
                  <span><strong>${letters[optIdx]}.</strong> ${this.escapeHtml(opt)}</span>
                  <span class="text-[10px] font-bold">${optIcon}</span>
                </div>
              `;
            }).join('')}
          </div>

          <div class="bg-blue-50/70 border border-blue-200/80 rounded-xl p-3 text-xs text-blue-950 space-y-1">
            <div class="font-bold flex items-center gap-1 text-blue-800">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              <span>Giải thích chi tiết:</span>
            </div>
            <div class="leading-relaxed text-slate-700 font-medium">
              ${this.escapeHtml(q.explanation || 'Đáp án theo chuẩn kiến thức giao tiếp và hội nhập quốc tế.')}
            </div>
          </div>
        </div>
      `;
    });

    if (filteredCount === 0) {
      html = `<div class="text-center py-8 text-slate-400 text-xs">Không có câu hỏi nào phù hợp với bộ lọc hiện tại.</div>`;
    }

    container.innerHTML = html;
  }

  // ==================== ADMIN / ORGANIZING COMMITTEE ====================
  populateSchoolFilters() {
    const filterSelect = document.getElementById('admin-filter-school');
    if (!filterSelect) return;

    this.schools.forEach(school => {
      const opt = document.createElement('option');
      opt.value = school;
      opt.textContent = school;
      filterSelect.appendChild(opt);
    });
  }

  renderAdminView() {
    this.renderAdminKPIs();
    this.renderAdminDistribution();
    this.renderAdminSubmissions();
    this.renderAdminQuestions();
  }

  renderAdminKPIs() {
    const list = this.submissions;
    const total = list.length;
    document.getElementById('admin-kpi-total').textContent = total;

    if (total === 0) {
      document.getElementById('admin-kpi-avg').textContent = '0.0';
      document.getElementById('admin-kpi-max').textContent = '0';
      document.getElementById('admin-kpi-excellent').textContent = '0%';
      return;
    }

    const sum = list.reduce((acc, cur) => acc + (cur.score || 0), 0);
    const avg = (sum / total).toFixed(1);
    const max = Math.max(...list.map(s => s.score || 0));
    const excellentCount = list.filter(s => s.score >= 75).length;
    const excellentRate = Math.round((excellentCount / total) * 100);

    document.getElementById('admin-kpi-avg').textContent = avg;
    document.getElementById('admin-kpi-max').textContent = max;
    document.getElementById('admin-kpi-excellent').textContent = `${excellentRate}%`;
  }

  renderAdminDistribution() {
    const container = document.getElementById('admin-distribution-bars');
    if (!container) return;

    const list = this.submissions;
    const total = list.length || 1;

    const ranges = [
      { label: 'Xuất sắc (90 - 100 điểm)', min: 90, max: 100, color: 'from-amber-500 to-yellow-400' },
      { label: 'Giỏi (75 - 89 điểm)', min: 75, max: 89, color: 'from-blue-600 to-indigo-500' },
      { label: 'Khá (50 - 74 điểm)', min: 50, max: 74, color: 'from-emerald-600 to-teal-500' },
      { label: 'Trung bình (< 50 điểm)', min: 0, max: 49, color: 'from-slate-500 to-slate-400' }
    ];

    let html = '';
    ranges.forEach(r => {
      const count = list.filter(s => s.score >= r.min && s.score <= r.max).length;
      const pct = Math.round((count / total) * 100);

      html += `
        <div class="space-y-1">
          <div class="flex justify-between text-xs font-semibold text-slate-700">
            <span>${r.label}</span>
            <span>${count} thí sinh (${pct}%)</span>
          </div>
          <div class="w-full h-3 bg-slate-100 rounded-full overflow-hidden">
            <div class="h-full bg-gradient-to-r ${r.color} transition-all duration-500" style="width: ${pct}%"></div>
          </div>
        </div>
      `;
    });
    container.innerHTML = html;
  }

  renderAdminSubmissions() {
    const schoolFilter = document.getElementById('admin-filter-school')?.value || 'all';
    const gradeFilter = document.getElementById('admin-filter-grade')?.value || 'all';
    const search = (document.getElementById('admin-search-text')?.value || '').trim().toLowerCase();

    let filtered = [...this.submissions];

    if (schoolFilter !== 'all') {
      filtered = filtered.filter(s => s.school === schoolFilter);
    }
    if (gradeFilter !== 'all') {
      filtered = filtered.filter(s => String(s.grade) === gradeFilter);
    }
    if (search) {
      filtered = filtered.filter(s => 
        (s.fullName && s.fullName.toLowerCase().includes(search)) ||
        (s.id && s.id.toLowerCase().includes(search)) ||
        (s.className && s.className.toLowerCase().includes(search))
      );
    }

    const countEl = document.getElementById('admin-filter-count');
    if (countEl) countEl.textContent = filtered.length;

    const tbody = document.getElementById('admin-submissions-tbody');
    if (!tbody) return;

    if (filtered.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="9" class="text-center py-6 text-slate-400 text-xs">
            Không tìm thấy thí sinh nào thỏa mãn bộ lọc.
          </td>
        </tr>
      `;
      return;
    }

    let html = '';
    filtered.forEach(s => {
      let warnBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800">0 lần</span>`;
      if (s.warningsCount === 1) {
        warnBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800">1 lần</span>`;
      } else if (s.warningsCount >= 2) {
        warnBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-red-100 text-red-800">${s.warningsCount} lần (Vi phạm)</span>`;
      }

      let scoreBadge = 'text-blue-700 font-extrabold';
      if (s.score >= 90) scoreBadge = 'text-amber-600 font-black';
      else if (s.score < 50) scoreBadge = 'text-slate-500 font-bold';

      html += `
        <tr class="hover:bg-slate-50/80 transition-colors">
          <td class="py-3 px-3 font-mono font-semibold text-slate-600">${this.escapeHtml(s.id)}</td>
          <td class="py-3 px-4 font-bold text-slate-800">${this.escapeHtml(s.fullName)}</td>
          <td class="py-3 px-4 text-slate-600">${this.escapeHtml(s.school)}</td>
          <td class="py-3 px-3"><span class="bg-slate-100 px-2 py-0.5 rounded text-slate-700 font-medium">${this.escapeHtml(s.className)}</span></td>
          <td class="py-3 px-3 text-center ${scoreBadge} text-sm">${s.score}</td>
          <td class="py-3 px-3 text-center font-mono text-slate-600">${s.durationFormatted || '15:00'}</td>
          <td class="py-3 px-3 text-center">${warnBadge}</td>
          <td class="py-3 px-4 font-semibold text-slate-700 text-[11px]">${this.escapeHtml(s.title || '')}</td>
          <td class="py-3 px-3 text-slate-400 font-mono text-[11px]">${s.submittedAt || ''}</td>
        </tr>
      `;
    });
    tbody.innerHTML = html;
  }

  exportExcelCSV() {
    // Generate UTF-8 BOM CSV for complete Excel compatibility
    const headers = [
      'SBD',
      'Họ và Tên',
      'Trường THPT',
      'Khối',
      'Lớp',
      'Điểm Số (Thang 100)',
      'Số Câu Đúng',
      'Tổng Số Câu',
      'Thời Gian Làm Bài',
      'Số Lần Cảnh Báo',
      'Danh Hiệu',
      'Thời Điểm Nộp'
    ];

    const rows = this.submissions.map(s => [
      `"${s.id}"`,
      `"${(s.fullName || '').replace(/"/g, '""')}"`,
      `"${(s.school || '').replace(/"/g, '""')}"`,
      `"Khối ${s.grade || ''}"`,
      `"${(s.className || '').replace(/"/g, '""')}"`,
      s.score,
      s.correctCount || Math.round(s.score / 5),
      s.totalQuestions || 20,
      `"${s.durationFormatted || ''}"`,
      s.warningsCount || 0,
      `"${(s.title || '').replace(/"/g, '""')}"`,
      `"${s.submittedAt || ''}"`
    ]);

    const csvContent = '\uFEFF' + headers.join(',') + '\r\n' + rows.map(r => r.join(',')).join('\r\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'Ket_Qua_Thi_Tieng_Anh_Hoi_Nhap_Quoc_Te.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  // ==================== QUESTION BANK MANAGER ====================
  filterAdminQuestions(type) {
    this.adminQFilter = type;
    document.querySelectorAll('.admin-q-filter-btn').forEach(btn => {
      btn.className = 'admin-q-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 text-slate-600 hover:bg-slate-200';
    });
    const activeBtn = document.getElementById(`qf-${type}`);
    if (activeBtn) {
      activeBtn.className = 'admin-q-filter-btn px-3 py-1.5 rounded-lg text-xs font-bold bg-blue-600 text-white';
    }
    this.renderAdminQuestions();
  }

  renderAdminQuestions() {
    const container = document.getElementById('admin-questions-list');
    if (!container) return;

    const p1Count = this.allQuestions.filter(q => Number(q.part) === 1).length;
    const p2Count = this.allQuestions.filter(q => Number(q.part) === 2).length;

    document.getElementById('admin-q-count-all').textContent = this.allQuestions.length;
    document.getElementById('admin-q-count-p1').textContent = p1Count;
    document.getElementById('admin-q-count-p2').textContent = p2Count;

    let list = this.allQuestions;
    if (this.adminQFilter === 'part1') list = list.filter(q => Number(q.part) === 1);
    if (this.adminQFilter === 'part2') list = list.filter(q => Number(q.part) === 2);

    let html = '';
    const letters = ['A', 'B', 'C', 'D'];

    list.forEach((q, idx) => {
      const partBadge = Number(q.part) === 2
        ? `<span class="bg-amber-100 text-amber-800 text-[10px] font-bold px-2 py-0.5 rounded">Phần 2: Hội nhập ASEAN</span>`
        : `<span class="bg-blue-100 text-blue-800 text-[10px] font-bold px-2 py-0.5 rounded">Phần 1: Tiếng Anh A1-A2</span>`;

      html += `
        <div class="rounded-xl border border-slate-200 p-4 bg-slate-50/50 hover:bg-white transition-all space-y-2.5">
          <div class="flex items-center justify-between flex-wrap gap-2">
            <div class="flex items-center gap-2">
              <span class="font-bold text-slate-500 text-xs">#${idx + 1}</span>
              ${partBadge}
              <span class="text-xs font-medium text-slate-500">${this.escapeHtml(q.category || '')}</span>
            </div>
            <div class="flex items-center gap-2">
              <button onclick="app.openEditQuestionModal('${q.id}')" class="px-2.5 py-1 text-xs font-bold rounded-lg border border-slate-300 hover:bg-slate-100 text-slate-700">Sửa</button>
              <button onclick="app.deleteQuestion('${q.id}')" class="px-2.5 py-1 text-xs font-bold rounded-lg border border-red-200 bg-red-50 hover:bg-red-100 text-red-600">Xóa</button>
            </div>
          </div>

          <div class="text-xs sm:text-sm font-semibold text-slate-800">
            ${this.escapeHtml(q.question)}
          </div>

          <div class="grid grid-cols-2 gap-2 text-xs">
            ${q.options.map((opt, oIdx) => {
              const isCorrect = oIdx === q.correct;
              return `
                <div class="p-2 rounded-lg border ${isCorrect ? 'border-emerald-500 bg-emerald-50 text-emerald-900 font-bold' : 'border-slate-200 bg-white text-slate-600'}">
                  ${letters[oIdx]}. ${this.escapeHtml(opt)} ${isCorrect ? ' ✓' : ''}
                </div>
              `;
            }).join('')}
          </div>

          <div class="text-[11px] text-slate-500 bg-slate-100 p-2 rounded-lg">
            <strong>Giải thích:</strong> ${this.escapeHtml(q.explanation || '')}
          </div>
        </div>
      `;
    });

    container.innerHTML = html;
  }

  openAddQuestionModal() {
    document.getElementById('qe-modal-title').textContent = 'Thêm Câu Hỏi Mới';
    document.getElementById('qe-id').value = '';
    document.getElementById('qe-part').value = '1';
    document.getElementById('qe-category').value = '';
    document.getElementById('qe-question').value = '';
    document.getElementById('qe-opt-0').value = '';
    document.getElementById('qe-opt-1').value = '';
    document.getElementById('qe-opt-2').value = '';
    document.getElementById('qe-opt-3').value = '';
    document.getElementById('qe-correct').value = '0';
    document.getElementById('qe-explanation').value = '';

    document.getElementById('modal-question-editor').classList.remove('hidden');
  }

  openEditQuestionModal(qId) {
    const q = this.allQuestions.find(item => item.id === qId);
    if (!q) return;

    document.getElementById('qe-modal-title').textContent = 'Chỉnh Sửa Câu Hỏi';
    document.getElementById('qe-id').value = q.id;
    document.getElementById('qe-part').value = String(q.part || 1);
    document.getElementById('qe-category').value = q.category || '';
    document.getElementById('qe-question').value = q.question || '';
    document.getElementById('qe-opt-0').value = q.options[0] || '';
    document.getElementById('qe-opt-1').value = q.options[1] || '';
    document.getElementById('qe-opt-2').value = q.options[2] || '';
    document.getElementById('qe-opt-3').value = q.options[3] || '';
    document.getElementById('qe-correct').value = String(q.correct || 0);
    document.getElementById('qe-explanation').value = q.explanation || '';

    document.getElementById('modal-question-editor').classList.remove('hidden');
  }

  closeQuestionModal() {
    document.getElementById('modal-question-editor').classList.add('hidden');
  }

  async handleSaveQuestion(event) {
    event.preventDefault();
    const qId = document.getElementById('qe-id').value;
    const part = Number(document.getElementById('qe-part').value);
    const category = document.getElementById('qe-category').value.trim();
    const question = document.getElementById('qe-question').value.trim();
    const options = [
      document.getElementById('qe-opt-0').value.trim(),
      document.getElementById('qe-opt-1').value.trim(),
      document.getElementById('qe-opt-2').value.trim(),
      document.getElementById('qe-opt-3').value.trim()
    ];
    const correct = Number(document.getElementById('qe-correct').value);
    const explanation = document.getElementById('qe-explanation').value.trim();

    const payload = { part, category, question, options, correct, explanation };

    if (qId) {
      const idx = this.allQuestions.findIndex(q => q.id === qId);
      if (idx !== -1) {
        this.allQuestions[idx] = { ...this.allQuestions[idx], ...payload };
      }
      try {
        await fetch(`/api/questions/${qId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
      } catch (e) {}
    } else {
      const newQ = { id: 'q_' + Date.now(), ...payload };
      this.allQuestions.push(newQ);
      try {
        await fetch('/api/questions', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
      } catch (e) {}
    }

    localStorage.setItem('gyc_questions', JSON.stringify(this.allQuestions));
    this.closeQuestionModal();
    this.renderAdminQuestions();
  }

  async deleteQuestion(qId) {
    if (!confirm("Bạn có chắc chắn muốn xóa câu hỏi này khỏi ngân hàng câu hỏi?")) return;

    this.allQuestions = this.allQuestions.filter(q => q.id !== qId);
    localStorage.setItem('gyc_questions', JSON.stringify(this.allQuestions));

    try {
      await fetch(`/api/questions/${qId}`, { method: 'DELETE' });
    } catch (e) {}

    this.renderAdminQuestions();
  }

  async resetDefaultQuestions() {
    if (!confirm("Khôi phục lại toàn bộ 30 câu hỏi chuẩn ban đầu?")) return;
    this.allQuestions = [...DEFAULT_QUESTIONS];
    localStorage.setItem('gyc_questions', JSON.stringify(this.allQuestions));
    this.renderAdminQuestions();
    alert("Đã làm mới ngân hàng câu hỏi về 30 câu chuẩn!");
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

// Global App Instance
window.app = new ContestApp();
